"""Six-course SEE review specification; never a live ParaLearn binding."""
import json
from pathlib import Path
import sys
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from schools.exam_blueprints import validate_blueprint
CODES = [f'SWP-{n:03}' for n in range(78, 84)]
MCQ_COUNTS = [7, 7, 7, 7, 6, 6]


def blueprint():
    items = [dict(id=f'SEE6-{code}-MCQ-{n:02}', type='MCQ', marks=1, course_codes=[code], question_binding=None) for code, count in zip(CODES, MCQ_COUNTS) for n in range(1, count + 1)]
    short = [
        ('An invented repair-and-learning venture calls sales proof of secure employment, treats user, payer and beneficiary as identical, labels itself cooperative without member arrangements and plans expansion after prototype clicks. Give five corrections.',
         'Separate mission from trading and evidenced outcomes; distinguish user, payer and beneficiary promises; describe actual operating and ownership arrangements; identify capacity and mission tensions; and frame a bounded innovation test with a disconfirming observation and review condition. No label or prototype authorises real trading.',
         ['Mission trading and outcome distinction', 'User payer beneficiary roles', 'Operating ownership and governance arrangements', 'Capacity and mission tension', 'Bounded innovation test and authority']),
        ('Ten invented favourable comments are multiplied into district sales. Price and timing were not discussed, alternative providers are ignored and a leading questionnaire asks why everyone loves the offer. Give five corrections.',
         'Distinguish need, interest and purchases; state selection, source and date limits; compare actual alternatives and practical access conditions; write a specific user/payer offer with neutral enquiry prompts; and report supplied findings with denominator, contrary evidence and a bounded next decision. Do not collect real personal records.',
         ['Need interest and transaction evidence', 'Selection source and date limits', 'Alternatives and access', 'Specific offer and neutral prompts', 'Bounded findings and next enquiry']),
        ('An invented service charges 50 per job, variable cost is 30 and fixed costs are 120. Ten jobs occur. Opening cash is 100, receipts are 80 and payments are 230. A later invoice is counted early; safe capacity is five jobs. Give five financial corrections, showing calculations.',
         'Contribution is 20 per job; ten jobs yield revenue 500, variable cost 300, contribution 200 and simplified surplus 80 before omissions. Current cash is minus 50, excluding later receipts. Break-even is six jobs under base assumptions, above five-job capacity; a cost rise to 35 would make it eight. State omitted mission costs and separate viability, cash and impact. No real borrowing or investment advice.',
         ['Unit contribution and supplied cost assumptions', 'Revenue contribution and simplified surplus arithmetic', 'Cash timing and minus-50 balance', 'Break-even capacity and sensitivity', 'Omissions mission and real-finance boundaries']),
        ('An invented equipment grant is treated as money for all wages; a loan repayment precedes receipts; a funder can replace elected members; unreadable terms are voted on; and students are asked to collect real deposits. Give five corrections.',
         'Respect restricted purpose and identify unfunded operations; examine repayment and cash obligations; scrutinise external control against member autonomy; provide understandable decision information and accountable roles with minority concerns retained; and keep transactions fictional, requiring verified legal/regulated-service authority for real activity. Cooperative identity is not a deposit-taking permission.',
         ['Finance restrictions and unfunded needs', 'Repayment timing and obligations', 'Member autonomy and external control', 'Meaningful information roles and accountability', 'Fictional exercise and regulated-service boundary']),
        ('An invented impact score is revenue renamed. Completions move from eight of ten to twelve of twenty while entry rules change; missing outcomes are deleted and reporting adoption is called proof of mission fidelity. Give five corrections.',
         'Separate resources, activities, outputs and outcomes; define measures, denominator, period and missing records; calculate the proportional fall from 80 to 60 percent; consider changed selection and other influences without causal overclaim; and distinguish measurement adoption from impact while reviewing mission tensions and communicating incomplete results honestly.',
         ['Evidence chain and proxy identity', 'Measure definitions and missing outcomes', 'Counts and proportion arithmetic', 'Comparability and attribution limits', 'Reporting versus mission and honest communication']),
        ('An invented launch proposal promises same-day service without staff, treats a 2026 paper using 2021 records as current local evidence, ignores a cash shortfall, expands after slides are complete and awards certificates from attendance. Give five corrections.',
         'Create a coherent problem, offer and dated claim record; compare options with capacity, cash and mission conditions; verify authority, resources, supply and governance before a limited fictional test; propose continue, modify or pause with an observation that could change the decision; and separate learning resources from verified course passes, the mixed ParaLearn school exam, human marking, independent moderation and authorised signatures.',
         ['Coherent proposal and honest dated evidence', 'Comparable options and feasibility', 'Readiness authority and bounded test', 'Conditional decision and learning review', 'Badge and school-certification gates']),
    ]
    for n, (prompt, model, criteria) in enumerate(short, 1):
        items.append(dict(id=f'SEE6-SA-{n:02}', type='SHORT_ANSWER', marks=5, course_codes=[CODES[n-1]], prompt=prompt, model_answer=model, human_marking_required=True,
            rubric=[dict(criterion=x, marks=1, scoring='0 absent/unsafe/unsupported; 1 accurate relevant reasoning applied to the invented case. Accept equivalent defensible reasoning.') for x in criteria]))
    essays = [
        ('Develop a conditional enterprise-launch decision across all six SEE courses for an invented repair-and-learning venture. Sales are treated as employment impact; ten comments become guaranteed demand; price and cost assumptions conceal a cash gap; an outside funder controls members; a target reduces learning hours; and expansion is promised before staffing or authority is checked. Compare options, show financial reasoning, preserve mission and specify a bounded review. Use invented records only.',
         'Integrate mission, payer/user/beneficiary roles and model tensions (078); bounded market evidence, alternatives and a credible accessible offer (079); explicit unit contribution, simplified costs, cash timing, break-even and capacity sensitivity (080); finance obligations, member control, inclusion and regulated-service limits (081); relevant measures, missing outcomes, attribution limits and mission review (082); and coherent options, authority/resource gates, a limited fictional test and continue/modify/pause decision (083). State responsible roles, assumptions and disconfirming evidence. No fundraising, real debts, registration, deposit-taking or service launch through coursework.'),
        ('Critique an invented claim that a new portal, a cooperative name, positive revenue and a large impact dashboard prove a viable and inclusive enterprise. The claim relies on a sector scoping review as a survival guarantee, a tool usability study as an outcome trial and a 2026 measurement-adoption paper as current local causal evidence. Public review questions are proposed unchanged for a graded exam and certificates are promised after viewing slides. Use all six SEE domains to correct the claims and propose the next authorised step.',
         'Separate novelty and trading from an evidenced mission mechanism (078); demand from selected interest and a label from a credible offer (079); revenue, contribution, profit, cash and capacity from a complete feasibility conclusion (080); identity, actual member control, financing obligations and access from regulated permission (081); proxies and reporting adoption from beneficiary outcomes, with design/date/context limits and missing results retained (082); and a bounded staged proposal from actual launch or professional authority (083). Public assessment exemplars require unpublished production banks before graded deployment. Badges need verified course passes; certification needs all six approved courses, configured mixed ParaLearn assessment, human written marking, independent moderation and authorised Head of Learning/Founder signatures.'),
    ]
    criteria = [('Mission model tensions and differentiated market evidence (078/079)', 3), ('Accurate cost cash break-even and capacity reasoning (080)', 3), ('Finance obligations cooperative control inclusion and authority (081)', 3), ('Impact evidence design limits and accountable mission review (082)', 3), ('Coherent staged proposal readiness and conditional review (083)', 3)]
    for n, (prompt, model) in enumerate(essays, 1):
        items.append(dict(id=f'SEE6-ESSAY-{n:02}', type='ESSAY', marks=15, course_codes=CODES, prompt=prompt, model_answer=model, human_marking_required=True,
            rubric=[dict(criterion=x, marks=w, scoring='0 absent/unsafe; 1 relevant limited point; 2 defensible applied reasoning with a gap; 3 coherent contextual reasoning with feasible action, authority and evidence limits. Accept equivalent defensible reasoning.') for x,w in criteria]))
    return dict(status='draft_for_review', school_code='SEE', curriculum_version='SEE-proposed-six-course-0.1.0', provider='ParaLearn CBT', provider_assessment_id=None, provider_contract_verified=False,
        required_courses=CODES, programme_target_course_count=6, draft_catalogue_complete=True, curriculum_complete=False, remaining_curriculum_titles=[], retained_course_domains={},
        scope_note='Six-title introductory assessment map. Forty MCQ slots allocated 7/7/7/7/6/6 for near-balanced coverage; each short answer focuses one course and both essays integrate all six. Public source items are review exemplars, not confidential production questions. Preserve every pre-existing course and CBT.',
        proposed_duration_minutes=210, duration_status='Proposed; accessibility review and learner piloting pending',
        marking_policy=dict(proposed_pass_percent=70, moderation_required=True, ai_only_finalisation=False, rubric_rule='Human criterion scores and reasons; independent identified human moderator; rubric version, moderation reasons and amendment/appeal history retained. Accept equivalent defensible reasoning. No automatic professional-competence decision.', appeals='Authorised review preserves the response, criterion marks and reasons, rubric version, moderation and dated amendment/appeal outcomes.'),
        certification=dict(authorised=False, requirements=['Course badge: approved course plus verified ParaLearn course CBT pass', 'Certificate: every approved school course plus final mixed ParaLearn exam with human written marking and independent moderation', 'Unpublished production banks and actual ParaLearn configuration required before launch', 'Head of Learning name/signature pending; Founder Prof. Mina Ogbanga; authorised signatures required']), items=items)


if __name__ == '__main__':
    data=blueprint(); print(validate_blueprint(data))
    (ROOT/'production_courseware/phase_thirteen/see_batch_01/school_exam_blueprint.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
